* { box-sizing: border-box; }
html { scroll-behavior: smooth; background: var(--black); }
body {
  margin: 0;
  color: var(--white);
  background:
    radial-gradient(circle at 15% 5%, rgba(229, 9, 20, .18), transparent 28rem),
