  text-shadow: 0 0 26px var(--glow);
}
.header-actions { display: flex; align-items: center; gap: 12px; }
.language-select {
  color: var(--white);
  background: rgba(16, 16, 16, .74);
  border: 1px solid rgba(255, 255, 255, .45);
  border-radius: 6px;
  padding: 8px 30px 8px 12px;
  min-height: 36px;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  border-radius: 6px;
  background: var(--red);
  color: var(--white);
  font-weight: 800;
  text-decoration: none;
  cursor: pointer;
  box-shadow: 0 16px 34px rgba(229, 9, 20, .22);
  transition: transform .2s ease, background .2s ease, box-shadow .2s ease;
}
.btn:hover, .btn:focus-visible { background: #f30d19; transform: translateY(-1px); box-shadow: 0 20px 44px rgba(229, 9, 20, .34); }
.btn-small { min-height: 36px; padding: 8px 17px; }
.btn-large { min-height: 58px; padding: 13px 28px; font-size: clamp(1.05rem, 2vw, 1.42rem); }
.btn.full { width: 100%; margin-top: 20px; }

.hero {
  position: relative;
