  place-items: center;
  overflow: hidden;
  border-bottom: 8px solid #232323;
  padding: 130px 20px 80px;
}
.poster-mosaic {
  position: absolute;
  inset: -8% -4%;
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
