.p4 { background: linear-gradient(135deg, #071f1d, #c80035, #070606); }
.p5 { background: linear-gradient(135deg, #271330, #dc155f, #050505); }
.p6 { background: linear-gradient(135deg, #101010, #3156a6, #040404); }
.hero-overlay { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.74), rgba(0,0,0,.52) 38%, rgba(0,0,0,.94)), radial-gradient(circle at center, transparent 0, rgba(0,0,0,.72) 72%); }
