.eyebrow { color: #ffd9dc; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 16px; font-size: clamp(2.55rem, 8vw, 5.25rem); line-height: .95; letter-spacing: -.07em; }
.hero-subtitle { margin-bottom: 30px; font-size: clamp(1.15rem, 3vw, 1.65rem); font-weight: 750; }
.email-capture { width: min(760px, 100%); margin: 0 auto; }
.email-capture p { font-size: clamp(1rem, 2vw, 1.18rem); color: #f2f2f2; }
.capture-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; }
input {
  width: 100%;
  min-height: 58px;
  padding: 16px 18px;
  color: var(--white);
  background: rgba(20, 20, 20, .78);
  border: 1px solid rgba(255,255,255,.5);
  border-radius: 6px;
  outline: none;
}
input:focus { border-color: var(--white); box-shadow: 0 0 0 3px rgba(229,9,20,.4); }
.form-message { display: block; min-height: 22px; margin-top: 10px; color: #9ff6b2; font-weight: 700; }

.section {
  width: min(var(--max), calc(100% - 40px));
  margin: 0 auto;
  padding: clamp(48px, 8vw, 76px) 0;
}
.content-band { border-top: 1px solid rgba(255,255,255,.06); }
h2 { margin-bottom: 22px; font-size: clamp(1.75rem, 4vw, 2.45rem); letter-spacing: -.045em; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.carousel-button {
  flex: 0 0 auto;
  width: 48px;
  height: 84px;
  border: 0;
  border-radius: 10px;
  color: var(--white);
  background: rgba(255,255,255,.12);
  font-size: 3rem;
  cursor: pointer;
}
.carousel-button:hover { background: rgba(255,255,255,.22); }
.carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(164px, 205px);
  gap: 22px;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scroll-snap-type: inline mandatory;
  scroll-behavior: smooth;
  padding: 14px 6px 22px 42px;
  scrollbar-color: var(--red) #171717;
}
.title-card {
  position: relative;
  scroll-snap-align: start;
  min-height: 292px;
  margin: 0;
  border-radius: 16px;
  isolation: isolate;
  transition: transform .25s ease;
}
.title-card:hover { transform: scale(1.045); }
.poster-art {
  position: absolute;
  inset: 0;
  border-radius: 16px;
  background: linear-gradient(155deg, #611018, #160708 72%);
  box-shadow: 0 18px 50px rgba(0,0,0,.55), inset 0 0 0 1px rgba(255,255,255,.1);
}
.poster-art::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(180deg, transparent 45%, rgba(0,0,0,.86)); }
.art-2 { background: linear-gradient(155deg, #34210d, #f0b13b 45%, #140704); }
.art-3 { background: linear-gradient(155deg, #2c1132, #d91b70, #090409); }
.art-4 { background: linear-gradient(155deg, #18212b, #45566b, #070707); }
.art-5 { background: linear-gradient(155deg, #2f1836, #b44eb7, #090309); }
.art-6 { background: linear-gradient(155deg, #111, #c50f18, #1e0b0b); }
.art-7 { background: linear-gradient(155deg, #071d32, #1d8ed0, #05070a); }
.art-8 { background: linear-gradient(155deg, #2a1220, #fa6a96, #090406); }
.art-9 { background: linear-gradient(155deg, #14142d, #ff2155, #07070e); }
.art-10 { background: linear-gradient(155deg, #2f1020, #dc255b, #100308); }
.rank {
  position: absolute;
  z-index: 2;
  left: -38px;
  bottom: 2px;
  color: #050505;
  -webkit-text-stroke: 3px rgba(255,255,255,.72);
  text-shadow: 0 0 20px rgba(0,0,0,.9);
  font-size: 7.8rem;
  font-weight: 1000;
  line-height: .8;
}
.rank-10 { left: -55px; font-size: 6.7rem; }
.title-card h3 { position: absolute; z-index: 3; left: 18px; right: 16px; bottom: 14px; margin: 0; font-size: 1.1rem; }

.feature-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.feature-card {
  position: relative;
  min-height: 280px;
  padding: 24px;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(140deg, #1a1b36 0%, #221326 52%, #2b090d 100%);
}
.feature-card::after { content: ""; position: absolute; inset: auto -40px -70px auto; width: 150px; height: 150px; background: radial-gradient(circle, rgba(229,9,20,.55), transparent 68%); }
.feature-card h3 { font-size: 1.35rem; line-height: 1.12; }
.feature-card p { color: var(--muted); line-height: 1.45; }
.feature-icon { position: absolute; right: 22px; bottom: 18px; color: #ff6070; font-size: 2.7rem; }

.faq-section { padding-top: 30px; }
.faq-list { display: grid; gap: 8px; }
.faq-item { background: #2d2d2d; border-radius: 2px; overflow: hidden; }
.faq-item button {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
  padding: 25px 28px;
  border: 0;
  color: var(--white);
  background: transparent;
  text-align: left;
  font-size: clamp(1.08rem, 2vw, 1.55rem);
  cursor: pointer;
}
.faq-item button:hover { background: #383838; }
.faq-plus { font-size: 2.4rem; line-height: 1; transition: transform .22s ease; }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height .28s ease; border-top: 1px solid transparent; }
.faq-answer p { margin: 0; padding: 0 28px 28px; color: #ededed; font-size: clamp(1rem, 2vw, 1.3rem); line-height: 1.45; }
.faq-item.open .faq-answer { max-height: 430px; border-top-color: rgba(0,0,0,.35); }
.faq-item.open .faq-plus { transform: rotate(45deg); }

.bottom-cta { text-align: center; border-top: 8px solid #232323; width: 100%; max-width: none; padding-inline: 20px; }
.bottom-cta h2 { margin-inline: auto; max-width: 760px; }
.compact { max-width: 760px; }

.site-footer {
  width: min(var(--max), calc(100% - 40px));
  margin: 0 auto;
  padding: 48px 0 68px;
  color: rgba(255,255,255,.72);
  border-top: 1px solid rgba(255,255,255,.08);
}
.footer-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px 34px; margin: 28px 0; }
.footer-grid a { color: inherit; font-size: .92rem; }
.footer-language { margin-bottom: 18px; }
.site-footer small { display: block; max-width: 760px; color: rgba(255,255,255,.58); }

.login-page { min-height: 100vh; background: radial-gradient(circle at top, rgba(229,9,20,.18), transparent 26rem), #000; }
.simple-header { position: relative; }
.login-main { min-height: 610px; display: grid; place-items: center; padding: 40px 20px 70px; }
.login-card {
  width: min(470px, 100%);
  padding: clamp(28px, 5vw, 48px);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 20px;
  background: rgba(12, 12, 12, .88);
  box-shadow: 0 30px 90px rgba(0,0,0,.8);
}
.login-card h1 { font-size: clamp(1.8rem, 5vw, 2.6rem); line-height: 1; margin-bottom: 10px; }
.login-card p { color: var(--muted); }
.login-card form { display: grid; gap: 10px; margin-top: 26px; }
.login-card label { color: #f0f0f0; font-weight: 700; }
.help-panel { margin-top: 24px; border-top: 1px solid var(--line); padding-top: 20px; }
.help-toggle { width: 100%; display: flex; justify-content: space-between; color: var(--white); background: none; border: 0; padding: 0; font-weight: 800; cursor: pointer; }
.help-content { display: grid; gap: 12px; max-height: 0; overflow: hidden; transition: max-height .25s ease; }
.help-content a { color: var(--muted); }
.help-panel.open .help-content { max-height: 140px; margin-top: 18px; }
.help-panel.open .help-toggle span { transform: rotate(45deg); }
.compact-footer { padding-top: 24px; }

@media (max-width: 920px) {
