  .poster-mosaic { grid-template-columns: repeat(3, minmax(130px, 1fr)); }
  .feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 640px) {
  .site-header { width: calc(100% - 28px); padding-top: 18px; }
  .logo { font-size: 1.55rem; }
  .header-actions { gap: 8px; }
  .language-select { max-width: 118px; padding-right: 8px; }
  .btn-small { padding-inline: 12px; }
  .hero { min-height: 690px; padding-inline: 14px; }
  .poster-mosaic { inset: -4% -35%; grid-template-columns: repeat(3, 150px); opacity: .5; }
  .poster { min-height: 220px; }
  .capture-row { grid-template-columns: 1fr; }
  .btn-large { width: 100%; }
  .section { width: calc(100% - 28px); }
  .carousel { grid-auto-columns: minmax(136px, 165px); gap: 18px; padding-left: 36px; }
  .title-card { min-height: 240px; }
  .rank { font-size: 6rem; left: -31px; }
  .rank-10 { left: -46px; font-size: 5.2rem; }
  .carousel-button { width: 42px; height: 58px; }
  .feature-grid { grid-template-columns: 1fr; }
  .feature-card { min-height: 220px; }
  .faq-item button { padding: 21px 18px; }
  .faq-answer p { padding: 0 18px 22px; }
  .site-footer { width: calc(100% - 28px); }
  .footer-grid { grid-template-columns: 1fr; }
  .simple-header { align-items: flex-start; }
  .login-main { padding-top: 24px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; }
}
EOF

cat > /app/output/script.js <<'EOF'
const carousel = document.querySelector('[data-carousel]');
const nextButton = document.querySelector('[data-carousel-next]');

if (carousel && nextButton) {
  nextButton.addEventListener('click', () => {
    const distance = Math.min(carousel.clientWidth * 0.82, 720);
    carousel.scrollBy({ left: distance, behavior: 'smooth' });
  });
}

document.querySelectorAll('[data-accordion]').forEach((accordion) => {
  accordion.querySelectorAll('.faq-item button').forEach((button) => {
    button.addEventListener('click', () => {
      const selectedItem = button.closest('.faq-item');
      accordion.querySelectorAll('.faq-item').forEach((item) => {
        const isSelected = item === selectedItem;
        item.classList.toggle('open', isSelected && !item.classList.contains('open'));
        item.querySelector('button').setAttribute('aria-expanded', String(item.classList.contains('open')));
      });
    });
  });
});

document.querySelectorAll('[data-signup-form]').forEach((form) => {
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const input = form.querySelector('input[type="email"]');
    const message = form.querySelector('.form-message');
    if (!input.checkValidity()) {
      input.reportValidity();
      return;
    }
    message.textContent = 'Great — your membership can start with this email.';
  });
});

const loginForm = document.querySelector('[data-login-form]');
if (loginForm) {
  loginForm.addEventListener('submit', (event) => {
    event.preventDefault();
    const message = loginForm.querySelector('.form-message');
    if (!loginForm.checkValidity()) {
      loginForm.reportValidity();
      return;
    }
    message.textContent = 'Credentials accepted for this demo.';
  });
}

const helpPanel = document.querySelector('[data-help]');
if (helpPanel) {
  const toggle = helpPanel.querySelector('.help-toggle');
  toggle.addEventListener('click', () => {
    helpPanel.classList.toggle('open');
    toggle.setAttribute('aria-expanded', String(helpPanel.classList.contains('open')));
  });
}
EOF

